import { useCallback, useState, ChangeEvent, KeyboardEvent } from 'react';
import { TextField, Tag, Stack } from '@jinx-ui/react';

interface TagPickerProps {
  label?: string;
  placeholder?: string;
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function TagPicker({
  label = 'Теги',
  placeholder = 'Введите тег и нажмите Enter',
  defaultTags = [],
  onChange,
}: TagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);
  const [inputValue, setInputValue] = useState('');

  const commitTags = useCallback(
    (nextTags: string[]) => {
      setTags(nextTags);
      onChange?.(nextTags);
    },
    [onChange],
  );

  const addTag = useCallback(
    (rawValue: string) => {
      const value = rawValue.trim();
      if (!value || tags.includes(value)) {
        setInputValue('');
        return;
      }
      commitTags([...tags, value]);
      setInputValue('');
    },
    [tags, commitTags],
  );

  const removeTag = useCallback(
    (tagToRemove: string) => {
      commitTags(tags.filter((tag) => tag !== tagToRemove));
    },
    [tags, commitTags],
  );

  const handleInputChange = useCallback((event: ChangeEvent<HTMLInputElement>) => {
    setInputValue(event.target.value);
  }, []);

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLInputElement>) => {
      if (event.key === 'Enter' || event.key === ',') {
        event.preventDefault();
        addTag(inputValue);
        return;
      }
      if (event.key === 'Backspace' && inputValue === '' && tags.length > 0) {
        removeTag(tags[tags.length - 1]);
      }
    },
    [inputValue, addTag, removeTag, tags],
  );

  return (
    <Stack direction="column" gap="sm" className="jx-tag-picker">
      <TextField
        label={label}
        placeholder={placeholder}
        value={inputValue}
        onChange={handleInputChange}
        onKeyDown={handleKeyDown}
      />
      {tags.length > 0 && (
        <Stack direction="row" wrap gap="xs" className="jx-tag-picker__list">
          {tags.map((tag) => (
            <Tag key={tag} onRemove={() => removeTag(tag)}>
              {tag}
            </Tag>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

